// The causal route's rule, called through the functions generated from the
// standard Mesh documents (sce/src/mesh/generated/, regenerated by
// sce/src/mesh/generate_envelope.sh). Every core generates the same documents,
// so the rule is one implementation on every core rather than a C++ copy the
// others were held to (docs/adr/0085, section 3.2, "One rule on every core").
//
// What remains here is the conversion between the runtime's CausalEntry and
// CausalKnown and the records the documents declare, and the bound of a vector
// the generated C++ lists do not hold themselves: a generated C++ list is a
// `std::vector`, which grows past its declared bound where the bounded
// backends refuse, so the bound is held here, after the call.

#include "mesh/CausalRules.h"

#include "generated/causal_admit.h"
#include "generated/causal_cut.h"
#include "generated/causal_lacks.h"
#include "generated/causal_raise.h"

#include <utility>

namespace SCE::Mesh {

namespace {

namespace gen = ::SCE::Generated;
using GenEntry = gen::CausalEntry::CausalEntryPayload;
using GenKnown = gen::CausalKnown::CausalKnownPayload;
using ::SCE::Forge::AlgorithmError;
using ::SCE::Forge::AlgorithmResult;
using ::SCE::Forge::Span;

GenEntry toGenerated(const CausalEntry &entry) {
    GenEntry g;
    g.hi = entry.hi;
    g.lo = entry.lo;
    g.seq = entry.seq;
    return g;
}

std::vector<GenEntry> toGenerated(Span<const CausalEntry> vector) {
    std::vector<GenEntry> out;
    out.reserve(vector.size());
    for (const auto &entry : vector) {
        out.push_back(toGenerated(entry));
    }
    return out;
}

std::vector<GenKnown> toGenerated(Span<const CausalKnown> known) {
    std::vector<GenKnown> out;
    out.reserve(known.size());
    for (const auto &mark : known) {
        GenKnown g;
        g.holderHi = mark.holderHi;
        g.holderLo = mark.holderLo;
        g.hi = mark.hi;
        g.lo = mark.lo;
        g.seq = mark.seq;
        out.push_back(g);
    }
    return out;
}

/// A generated vector as the runtime holds it, refused past the bound of a
/// view.
AlgorithmResult<std::vector<CausalEntry>> bounded(const std::vector<GenEntry> &vector) {
    if (vector.size() > kCausalVectorBound) {
        return AlgorithmResult<std::vector<CausalEntry>>::failure(AlgorithmError::CapacityExceeded);
    }
    std::vector<CausalEntry> out;
    out.reserve(vector.size());
    for (const auto &g : vector) {
        CausalEntry entry;
        entry.hi = g.hi;
        entry.lo = g.lo;
        entry.seq = g.seq;
        out.push_back(entry);
    }
    return AlgorithmResult<std::vector<CausalEntry>>::success(std::move(out));
}

}  // namespace

AlgorithmResult<CausalAdmission> causalAdmit(Span<const CausalEntry> delivered, const CausalEntry &dot,
                                             Span<const CausalEntry> context) {
    const auto admitted =
        gen::CausalAdmit::causal_admit(toGenerated(delivered), toGenerated(dot), toGenerated(context));
    if (!admitted.ok()) {
        return AlgorithmResult<CausalAdmission>::failure(admitted.error());
    }
    // The runtime's enum declares the document's values over its carrier, as
    // PatternKind mirrors pattern_kind.scxml, so the conversion is the number.
    return AlgorithmResult<CausalAdmission>::success(
        static_cast<CausalAdmission>(gen::CausalAdmission::to_underlying(admitted.value())));
}

AlgorithmResult<std::vector<CausalEntry>> causalRaise(Span<const CausalEntry> vector, Span<const CausalEntry> other) {
    return bounded(gen::CausalRaise::causal_raise(toGenerated(vector), toGenerated(other)));
}

bool causalLacks(Span<const CausalEntry> vector, const CausalEntry &dot) {
    return gen::CausalLacks::causal_lacks(toGenerated(vector), toGenerated(dot));
}

AlgorithmResult<std::vector<CausalEntry>> causalCut(std::uint32_t members, Span<const CausalKnown> known) {
    return bounded(gen::CausalCut::causal_cut(members, toGenerated(known)));
}

}  // namespace SCE::Mesh
